import{_ as e,o as s,c as t,ag as l}from"./chunks/framework.DGzMGr_a.js";const m=JSON.parse('{"title":"GTMyWorld 家园系统","description":"","frontmatter":{},"headers":[],"relativePath":"gtmyworld/index.md","filePath":"gtmyworld/index.md","lastUpdated":1784956301000}'),n={name:"gtmyworld/index.md"};function i(o,a,d,p,r,c){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="gtmyworld-家园系统" tabindex="-1">GTMyWorld 家园系统 <a class="header-anchor" href="#gtmyworld-家园系统" aria-label="Permalink to &quot;GTMyWorld 家园系统&quot;">​</a></h1><p>GTMyWorld 面向生存服、RPG 服和多子服网络提供完整家园玩法。玩家通过 GUI 创建、升级、访问和管理家园；服务器管理员可以配置模板、等级、成员上限、访问规则、细粒度权限、家园核心和多种经济。</p><p>GTMyWorld 采用原创世界优化方案，让多个家园安全地共享家园世界，在保留独立边界和权限的同时减少世界数量与常驻资源占用。单端和多家园服都使用同一套配置。</p><h2 id="安装要求" tabindex="-1">安装要求 <a class="header-anchor" href="#安装要求" aria-label="Permalink to &quot;安装要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>必装</td><td>GTCore</td></tr><tr><td>可选</td><td>PlaceholderAPI、Vault、PlayerPoints、NeigeItems、MythicMobs、Adyeshach</td></tr><tr><td>服务端</td><td>Spigot/Paper/Purpur/Folia/CatServer等核心支持 1.12.2 - 26.x</td></tr><tr><td>Java</td><td>Java 版本按服务端要求选择</td></tr></tbody></table><p>将 GTCore 放入 <code>plugins</code>，GTMyWorld 由 GTCore 授权后加载。首次加载生成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/GTMyWorld/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ currencies.yml</span></span>
<span class="line"><span>├─ levels.yml</span></span>
<span class="line"><span>├─ templates.yml</span></span>
<span class="line"><span>├─ core.yml</span></span>
<span class="line"><span>├─ permissions.yml</span></span>
<span class="line"><span>├─ messages.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>└─ templates/</span></span></code></pre></div><p>普通配置修改后执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gtmw admin reload</span></span></code></pre></div><p>修改存储连接、<code>server.id</code> 或世界池容量后重启服务器。</p><h2 id="玩家入口" tabindex="-1">玩家入口 <a class="header-anchor" href="#玩家入口" aria-label="Permalink to &quot;玩家入口&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gtmw</span></span></code></pre></div><p>主界面包含返回家园、改名与介绍、设置传送点、邀请成员、家园设置、成员与权限、家园核心、升级、排行和公开家园。玩家不需要记忆完整指令。</p><p>创建第一个家园：</p><ol><li>输入 <code>/gtmw</code>。</li><li>打开模板选择界面。</li><li>选择一个满足权限、物品和货币要求的模板。</li><li>创建完成后自动进入家园核心位置。</li></ol><h2 id="管理员配置顺序" tabindex="-1">管理员配置顺序 <a class="header-anchor" href="#管理员配置顺序" aria-label="Permalink to &quot;管理员配置顺序&quot;">​</a></h2><ol><li>在 <code>config.yml</code> 设置单端或多家园服、世界池容量和服务器全局限制。</li><li>在 <code>currencies.yml</code> 配置金币、点券或其他自定义货币。</li><li>在 <code>levels.yml</code> 配置家园直径、成员位和升级消耗。</li><li>使用模板工具保存建筑区域，再在 <code>templates.yml</code> 开放模板。</li><li>在 <code>permissions.yml</code> 设置游客和成员默认权限。</li><li>需要战争玩法时在 <code>config.yml</code> 开启战争模式，并在 <code>core.yml</code> 配置燃料与赎回。</li></ol><h2 id="文档入口" tabindex="-1">文档入口 <a class="header-anchor" href="#文档入口" aria-label="Permalink to &quot;文档入口&quot;">​</a></h2><ul><li><a href="/gtmyworld/config">主配置与世界池</a></li><li><a href="/gtmyworld/content">模板、等级、物品库与多货币</a></li><li><a href="/gtmyworld/permissions-core">权限、GUI 与家园核心</a></li><li><a href="/gtmyworld/commands-placeholders">命令与 PlaceholderAPI 变量</a></li></ul>`,19)])])}const g=e(n,[["render",i]]);export{m as __pageData,g as default};
